			for (y = 0; y < this.dims.y; y++) {
				this.cells[z][y] = [];
				for (x = 0; x < this.dims.x; x++) {
					this.cells[z][y][x] = new Cell3D({x: x*sizes.x, y: y*sizes.y, z: z*sizes.z}, sizes);
