function setup() {
	mode3D = true; // random() < 0.5;
  createCanvas(S=max(windowWidth, windowHeight), S, mode3D ? WEBGL : P2D);
  frameRate(30);
	bg = color(4, 4, 12);

  const SX = width / NUM_W;
  const SY = height / NUM_H;
  grid = mode3D ? new Grid3D({x:0, y:0, z:0}, {x: NUM_W, y: NUM_H, z: NUM_H}, {x: SX, y: SY, z: SX}) : new Grid(NUM_W, NUM_H, SX, SY);
